#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# The repository-setup wizard (#198): the one-off human steps of #48. It
# registers the repository's GitHub App and installs it on this repository,
# stores its client ID and a private key as the variable APP_CLIENT_ID and
# the secret APP_PRIVATE_KEY, installs the Renovate GitHub App, and applies
# the repository settings with `pnpm repo:settings`.
#
# From the repository root, in Git Bash (Windows) or a Linux shell:
#
#   bash release/repo-setup.sh            the real run
#   bash release/repo-setup.sh --dry-run  prints every command, changes nothing
#
# It checks what gh can check and stops at the first failed check, saying
# what to fix. The App's owner, permissions and installation it checks as
# the App itself (`pnpm github-app check`, a JWT signed with the key); which
# repositories an installation reaches, and Renovate's installation scope,
# it asks the maintainer to confirm. It never prints the private key: the
# key file goes to `gh secret set` on its standard input. It is safe to
# re-run: the App stages are skipped when the variable and the secret
# exist, Renovate's installation when its Dependency Dashboard issue
# exists, the settings when they read back as committed.
#
# The dry run still runs the read-only checks (gh, git, what the repository
# holds, `pnpm repo:settings --dry-run`). It only warns about the branch,
# the working tree and what master lacks, so the wizard can be reviewed
# from any branch; it answers every confirmation with yes, opens no browser,
# and prints the commands that change something instead of running them.

readonly REPO_OWNER=phmilk
readonly REPO_NAME=reforged-ts
readonly REPO="$REPO_OWNER/$REPO_NAME"
readonly CLIENT_ID_VARIABLE=APP_CLIENT_ID
readonly PRIVATE_KEY_SECRET=APP_PRIVATE_KEY
readonly RULESET_FILE=.github/rulesets/master.json
readonly RENOVATE_CONFIG=renovate.json5
readonly GUIDE=docs/release.md
readonly RERUN="bash release/repo-setup.sh"

usage() {
  printf 'Usage: %s [--dry-run]\n' "$RERUN"
  printf '  The one-off setup of %s: its GitHub App, Renovate and settings (#48).\n' "$REPO"
}

DRY_RUN=false
if [[ $# -gt 1 ]]; then usage >&2; exit 2; fi
case "${1:-}" in
  "") ;;
  --dry-run) DRY_RUN=true ;;
  -h | --help) usage; exit 0 ;;
  *) usage >&2; exit 2 ;;
esac

# Git Bash rewrites arguments that look like POSIX paths. Paths handed to
# native programs go through cygpath instead (see native_path).
export MSYS_NO_PATHCONV=1 MSYS2_ARG_CONV_EXCL='*'

# Nothing this wizard captures is persisted locally: no value is read from
# or written to a .env file. The GitHub variable and secret are the store.
ENV_FILE=/dev/null

ERR_FILE=$(mktemp)
trap 'rm -f "$ERR_FILE"' EXIT
trap 'exit 130' INT TERM

# In the dry run, nothing waits for the human and no browser opens: the
# library's gates print what they would ask instead.
if $DRY_RUN; then
  _clear() { :; }
  pause() { printf '  %s%s%s %s(dry run: continues)%s\n' "$DIM" "${1:-Press Enter to continue}" "$RESET" "$YELLOW" "$RESET"; }
  confirm() { printf '  %s? %s%s %s(dry run: answered yes)%s\n' "$YELLOW" "$1" "$RESET" "$YELLOW" "$RESET"; }
  open_url() { printf '  %s↗ would open%s %s\n' "$GREEN" "$RESET" "$1"; }
fi

ok() { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }

# fail "what failed" ["what to fix"...] stops the wizard.
fail() {
  printf '\n  %s%s✗ %s%s\n' "$BOLD" "$RED" "$1" "$RESET" >&2
  shift
  local line
  for line in "$@"; do printf '    %s\n' "$line" >&2; done
  printf '\n  %sThen re-run: %s%s%s\n\n' "$DIM" "$RERUN" "$($DRY_RUN && printf ' --dry-run')" "$RESET" >&2
  exit 1
}

# soft_fail stops the wizard, except in the dry run, where it only warns:
# the checks of the checkout and of master, so the dry run can be reviewed
# from any branch before the pull request adding this wizard merges.
soft_fail() {
  if $DRY_RUN; then
    warn "$1 (a real run stops here)"
    shift
    local line
    for line in "$@"; do note "  $line"; done
    return 0
  fi
  fail "$@"
}

# run CMD... prints the command, then runs it; in the dry run it only prints.
run() {
  printf '  %s$ %s%s\n' "$BOLD" "$*" "$RESET"
  $DRY_RUN || "$@"
}

# show CMD... prints the command, then runs it, in the dry run too: for the
# read-only commands whose output the maintainer reads.
show() {
  printf '  %s$ %s%s\n' "$BOLD" "$*" "$RESET"
  "$@"
}

# native_path PATH: PATH as native programs (node, pnpm) read it.
native_path() {
  if command -v cygpath >/dev/null 2>&1; then cygpath -m "$1"; else printf '%s' "$1"; fi
}

# shell_path PATH: a path as typed or pasted (quoted, ~/..., C:\...), as
# this shell reads it.
shell_path() {
  local path="$1"
  path="${path#[\"\']}"
  path="${path%[\"\']}"
  if [[ "$path" == \~/* ]]; then path="$HOME/${path:2}"; fi
  if command -v cygpath >/dev/null 2>&1; then path=$(cygpath -u "$path"); fi
  printf '%s' "$path"
}

# gh_read ARGS...: gh's output for a read-only query; empty when it fails
# (a 404 included; gh api prints the error body on stdout), its message
# kept in ERR_FILE.
gh_read() {
  local out
  if out=$(gh "$@" 2>"$ERR_FILE"); then printf '%s\n' "$out"; fi
}

# app_stored: whether the repository holds the App's variable and secret.
app_stored() {
  [[ -n "$(gh_read variable get "$CLIENT_ID_VARIABLE" --repo "$REPO")" ]] &&
    [[ -n "$(gh_read secret list --repo "$REPO" --json name --jq ".[] | select(.name == \"$PRIVATE_KEY_SECRET\") | .name")" ]]
}

# renovate_dashboard: the number of Renovate's open Dependency Dashboard
# issue, the sign that it is installed and read the configuration.
renovate_dashboard() {
  gh_read issue list --repo "$REPO" --author app/renovate --state open \
    --search 'Dependency Dashboard in:title' --json number --jq '.[0].number // empty'
}

# renovate_onboarding: the number of Renovate's open onboarding pull request.
renovate_onboarding() {
  gh_read pr list --repo "$REPO" --author app/renovate --state open \
    --head renovate/configure --json number --jq '.[0].number // empty'
}

# settings_problems prints one line per repository setting that does not
# read back as committed; nothing when all do.
settings_problems() {
  local expected id actual merge pages
  expected=$(node -e '
    const ruleset = JSON.parse(require("fs").readFileSync(process.argv[1], "utf8"));
    const checks = ruleset.rules.filter((rule) => rule.type === "required_status_checks")
      .flatMap((rule) => rule.parameters.required_status_checks.map((check) => check.context));
    process.stdout.write("active;refs/heads/master;" + checks.sort().join(","));
  ' "$RULESET_FILE")
  id=$(gh_read api "repos/$REPO/rulesets?includes_parents=false" --jq '.[] | select(.name == "master") | .id')
  if [[ -z "$id" ]]; then
    printf 'No ruleset named master.\n'
  else
    actual=$(gh_read api "repos/$REPO/rulesets/$id" --jq '[.enforcement, (.conditions.ref_name.include | join(",")), ([.rules[] | select(.type == "required_status_checks") | .parameters.required_status_checks[].context] | sort | join(","))] | join(";")')
    [[ "$actual" == "$expected" ]] ||
      printf 'The ruleset master reads "%s" (enforcement;branches;required checks), not "%s".\n' "$actual" "$expected"
  fi
  merge=$(gh_read api "repos/$REPO" --jq '"\(.allow_squash_merge) \(.allow_merge_commit) \(.allow_rebase_merge) \(.allow_auto_merge) \(.delete_branch_on_merge)"')
  [[ "$merge" == "true false false true true" ]] ||
    printf 'Merge settings (squash, merge commits, rebase, auto-merge, delete head branches) read "%s", not "true false false true true".\n' "$merge"
  pages=$(gh_read api "repos/$REPO/pages" --jq .build_type)
  [[ "$pages" == workflow ]] || printf 'The Pages source is "%s", not GitHub Actions (workflow).\n' "${pages:-off}"
  [[ -n "$(gh_read api "repos/$REPO/labels/game-patch" --jq .name)" ]] || printf 'No game-patch label.\n'
}

# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=7
APP_DONE=false # the variable and the secret exist and are kept
CLIENT_ID=""
KEY_FILE=""
INSTALL_PAGE=""

if $DRY_RUN; then
  banner "Setup of $REPO (dry run: nothing is changed)"
else
  banner "Setup of $REPO"
fi

# ── 1. Before anything ────────────────────────────────────────────────────
stage "Check gh, your rights and the checkout"

for tool in git gh node pnpm; do
  command -v "$tool" >/dev/null 2>&1 || fail "$tool is not on the PATH." "Install it; the root README lists the Toolchain, gh is https://cli.github.com."
done
ok "git, gh, node and pnpm are on the PATH"

ROOT=$(git rev-parse --show-toplevel 2>/dev/null) ||
  fail "This is not a git checkout." "Run the wizard from a clone of $REPO."
cd "$ROOT"
[[ -f "$RULESET_FILE" && -f release/src/cli/github-app.ts ]] ||
  fail "$ROOT is not the $REPO_NAME repository." "Run the wizard from a clone of $REPO."

gh auth status >/dev/null 2>"$ERR_FILE" ||
  fail "gh is not logged in: $(head -n 1 "$ERR_FILE")" "gh auth login"
ADMIN=$(gh_read api "repos/$REPO" --jq .permissions.admin)
if [[ "$ADMIN" == true ]]; then
  ok "gh is logged in as $(gh_read api user --jq .login), an administrator of $REPO"
else
  fail "gh's login is not an administrator of $REPO${ADMIN:+ (admin: $ADMIN)}. $(head -n 1 "$ERR_FILE")" \
    "Log in as the maintainer: gh auth login"
fi

BRANCH=$(git rev-parse --abbrev-ref HEAD)
if [[ "$BRANCH" == master ]]; then
  ok "on master"
else
  soft_fail "The checkout is on $BRANCH, not master." "git switch master && git pull --ff-only"
fi

if [[ -z "$(git status --porcelain)" ]]; then
  ok "the working tree is clean"
else
  soft_fail "The working tree has changes:" "$(git status --short)" "Commit, stash or discard them: the settings applied are master's."
fi

if git fetch --quiet origin master 2>"$ERR_FILE"; then
  if [[ "$(git rev-parse HEAD)" == "$(git rev-parse origin/master)" ]]; then
    ok "HEAD is origin/master"
  else
    soft_fail "HEAD is not origin/master." "git switch master && git pull --ff-only"
  fi
else
  fail "git fetch origin master failed: $(cat "$ERR_FILE")" "Check your network and your access to $REPO."
fi

run pnpm install --frozen-lockfile || fail "pnpm install failed." "Read the error above."
pause "Press Enter to continue"

# ── 2 to 5. The GitHub App ────────────────────────────────────────────────
stage "Register the GitHub App"

if app_stored; then
  ok "$REPO holds the variable $CLIENT_ID_VARIABLE and the secret $PRIVATE_KEY_SECRET: the App was set up on an earlier run."
  if confirm "Set the App up again (another App, or a new private key)?"; then
    note "For a new key of the same App, do not register another: answer yes below."
  else
    APP_DONE=true
  fi
fi

if $APP_DONE; then
  pause "Press Enter to continue"
else
  say "The workflows open their pull requests and the Patch-watch issue as this"
  say "App, with short-lived tokens (release.yml, patch-watch.yml, docs.yml)."
  say "The page opens pre-filled; check each value before creating the App:"
  URL=$(pnpm -s github-app url --repo "$REPO") || fail "pnpm github-app url failed." "Read the error above."
  open_url "$URL"
  say "  GitHub App name         ${BOLD}$REPO_NAME-bot${RESET} (any free name: the workflows use the client ID)"
  say "  Homepage URL            ${BOLD}https://github.com/$REPO${RESET}"
  say "  Webhook                 ${BOLD}Active unticked${RESET}"
  say "  Repository permissions  ${BOLD}Contents, Issues, Pull requests: Read and write${RESET};"
  say "                          Metadata: Read-only (GitHub adds it); every other: No access"
  say "  Organization, Account   ${BOLD}No access${RESET} for every permission"
  say "  Where can this GitHub App be installed?  ${BOLD}Only on this account${RESET}"
  step "Create GitHub App. If an earlier run created it, do not create another:"
  step "open it from https://github.com/settings/apps instead."
  confirm "Is the App created, owned by $REPO_OWNER?" ||
    fail "No App yet." "Create it on the page above."
fi

stage "The App's client ID and a private key"

if $APP_DONE; then
  ok "Kept from an earlier run."
  pause "Press Enter to continue"
else
  say "On the App's settings page (General):"
  step "Copy the ${BOLD}Client ID${RESET} (it starts with Iv), not the App ID (a number)."
  if $DRY_RUN; then
    note "  (dry run: asks for the client ID)"
    CLIENT_ID="<client ID>"
  else
    ask CLIENT_ID "Paste the client ID:"
    CLIENT_ID="${CLIENT_ID//[[:space:]]/}"
    if [[ "$CLIENT_ID" =~ ^[0-9]+$ ]]; then
      fail "$CLIENT_ID is the App ID." "Copy the Client ID, next to it on the App's settings page."
    fi
    [[ "$CLIENT_ID" =~ ^Iv[A-Za-z0-9._-]+$ ]] ||
      fail "'$CLIENT_ID' is not a client ID (it starts with Iv)." "Copy the Client ID from the App's settings page."
  fi
  step "Under Private keys, ${BOLD}Generate a private key${RESET}: the browser downloads a .pem file."
  if $DRY_RUN; then
    note "  (dry run: asks for the path of the .pem file)"
    KEY_FILE="<key file>"
  else
    ask KEY_PATH "Path of the downloaded .pem file (its path, not its content):"
    KEY_FILE=$(shell_path "$KEY_PATH")
    [[ -f "$KEY_FILE" && -r "$KEY_FILE" ]] ||
      fail "$KEY_FILE is not a readable file." "Give the path of the downloaded .pem file, such as ~/Downloads/$REPO_NAME-bot.<date>.private-key.pem"
    grep -q -- '-----BEGIN RSA PRIVATE KEY-----' "$KEY_FILE" ||
      fail "$KEY_FILE is not a private key the App's page generated." "Give the path of the downloaded .pem file."
    KEY_FILE=$(native_path "$KEY_FILE")
  fi
  say ""
  say "Checking the App as the App itself (a token signed with the key):"
  if $DRY_RUN; then
    run pnpm -s github-app check --repo "$REPO" --client-id "$CLIENT_ID" --private-key "$KEY_FILE"
    INSTALL_PAGE="https://github.com/apps/<the App's slug>/installations/new"
  else
    printf '  %s$ pnpm -s github-app check --repo %s --client-id %s --private-key %s%s\n' "$BOLD" "$REPO" "$CLIENT_ID" "$KEY_FILE" "$RESET"
    REPORT=$(pnpm -s github-app check --repo "$REPO" --client-id "$CLIENT_ID" --private-key "$KEY_FILE") ||
      fail "The App is not as the workflows need it (above)." "Fix it on the App's settings page: https://github.com/settings/apps"
    while IFS= read -r line; do note "  $line"; done <<<"$REPORT"
    INSTALL_PAGE=$(sed -n 's/^Installation page: //p' <<<"$REPORT")
    ok "the client ID and the key are the App's, with the permissions the workflows need and no webhook"
  fi
  pause "Press Enter to continue"
fi

stage "Install the App on $REPO"

if $APP_DONE; then
  ok "Kept from an earlier run."
  pause "Press Enter to continue"
else
  open_url "$INSTALL_PAGE"
  step "Install it on ${BOLD}$REPO_OWNER${RESET}."
  step "Repository access: ${BOLD}Only select repositories${RESET} → ${BOLD}$REPO_NAME${RESET}, and nothing else."
  step "Install."
  pause "Press Enter once it is installed"
  if $DRY_RUN; then
    run pnpm -s github-app check --repo "$REPO" --client-id "$CLIENT_ID" --private-key "$KEY_FILE" --installed
  else
    printf '  %s$ pnpm -s github-app check ... --installed%s\n' "$BOLD" "$RESET"
    REPORT=$(pnpm -s github-app check --repo "$REPO" --client-id "$CLIENT_ID" --private-key "$KEY_FILE" --installed) ||
      fail "The installation is not as the workflows need it (above)." "Fix it, then re-run. The account's installations: https://github.com/settings/installations"
    while IFS= read -r line; do note "  $line"; done <<<"$REPORT"
    ok "installed on $REPO_OWNER, on selected repositories, with the permissions accepted"
  fi
  note "Which repositories an installation reaches, only its settings page shows."
  confirm "Does its Repository access list $REPO_NAME only?" ||
    fail "The App reaches other repositories." "Remove them under Repository access: https://github.com/settings/installations"
fi

stage "Store the client ID and the private key"

if $APP_DONE; then
  ok "Kept from an earlier run: $CLIENT_ID_VARIABLE and $PRIVATE_KEY_SECRET."
  pause "Press Enter to continue"
else
  run gh variable set "$CLIENT_ID_VARIABLE" --repo "$REPO" --body "$CLIENT_ID" ||
    fail "gh variable set failed." "Read the error above."
  # The key goes to gh on its standard input: never on a command line,
  # never printed.
  printf '  %s$ gh secret set %s --repo %s < %s%s\n' "$BOLD" "$PRIVATE_KEY_SECRET" "$REPO" "$KEY_FILE" "$RESET"
  if ! $DRY_RUN; then
    gh secret set "$PRIVATE_KEY_SECRET" --repo "$REPO" <"$(shell_path "$KEY_FILE")" ||
      fail "gh secret set failed." "Read the error above."
    WRITTEN_SECRET+=("$PRIVATE_KEY_SECRET")
  fi
  say ""
  say "Checking:"
  if $DRY_RUN; then
    run gh variable get "$CLIENT_ID_VARIABLE" --repo "$REPO"
    run gh secret list --repo "$REPO"
  else
    [[ "$(gh_read variable get "$CLIENT_ID_VARIABLE" --repo "$REPO")" == "$CLIENT_ID" ]] ||
      fail "The variable $CLIENT_ID_VARIABLE does not read back as $CLIENT_ID." "gh variable set $CLIENT_ID_VARIABLE --repo $REPO --body <client ID>"
    ok "the variable $CLIENT_ID_VARIABLE is $CLIENT_ID"
    app_stored || fail "The secret $PRIVATE_KEY_SECRET is not listed." "gh secret set $PRIVATE_KEY_SECRET --repo $REPO < <key file>"
    ok "the secret $PRIVATE_KEY_SECRET is set"
  fi
  note "The .pem file is no longer needed: delete it, or keep it offline. A lost"
  note "key is replaced by generating a new one and re-running this wizard."
  pause "Press Enter to continue"
fi

# ── 6. Renovate ───────────────────────────────────────────────────────────
stage "Install Renovate"

if git cat-file -e "origin/master:$RENOVATE_CONFIG" 2>/dev/null; then
  ok "$RENOVATE_CONFIG is on master"
else
  soft_fail "$RENOVATE_CONFIG is not on master." \
    "Merge the pull request adding it first: installed before it, Renovate opens an" \
    "onboarding pull request instead of reading the configuration."
fi

DASHBOARD=$(renovate_dashboard)
if $DRY_RUN; then
  show gh issue list --repo "$REPO" --author app/renovate --state open --search 'Dependency Dashboard in:title'
fi
if [[ -n "$DASHBOARD" ]]; then
  ok "Renovate is installed: its Dependency Dashboard is issue #$DASHBOARD"
else
  say "Renovate opens the weekly dependency pull requests of $RENOVATE_CONFIG."
  open_url "https://github.com/apps/renovate/installations/new"
  step "Install it on ${BOLD}$REPO_OWNER${RESET} (Configure, when it is already on the account)."
  step "Repository access: ${BOLD}Only select repositories${RESET}, with ${BOLD}$REPO_NAME${RESET} among them."
  step "Install (or Save)."
  note "It finds $RENOVATE_CONFIG on master, so it opens no onboarding pull request;"
  note "within minutes it opens a Dependency Dashboard issue, then its first pull"
  note "requests in the Monday 00:00-04:00 UTC window."
  pause "Press Enter once it is installed"
  say ""
  if $DRY_RUN; then
    note "A real run then waits up to 10 minutes for the Dependency Dashboard issue."
  else
    say "Waiting for its Dependency Dashboard issue (up to 10 minutes):"
    for attempt in $(seq 1 20); do
      DASHBOARD=$(renovate_dashboard)
      [[ -n "$DASHBOARD" || -n "$(renovate_onboarding)" || $attempt -eq 20 ]] && break
      sleep 30
    done
    if [[ -n "$DASHBOARD" ]]; then
      ok "Renovate is installed: its Dependency Dashboard is issue #$DASHBOARD"
    else
      warn "No Dependency Dashboard yet: Renovate's first run can take longer."
      confirm "Is Renovate listed at https://github.com/$REPO/settings/installations?" ||
        fail "Renovate is not installed." "Install it from https://github.com/apps/renovate/installations/new"
    fi
  fi
fi

ONBOARDING=$(renovate_onboarding)
if $DRY_RUN; then
  show gh pr list --repo "$REPO" --author app/renovate --state open --head renovate/configure
fi
if [[ -n "$ONBOARDING" ]]; then
  warn "Renovate opened the onboarding pull request #$ONBOARDING: close it, never merge it"
  warn "(the renovate.json it adds would take precedence over $RENOVATE_CONFIG)."
  confirm "Close #$ONBOARDING and delete its branch now?" ||
    fail "The onboarding pull request #$ONBOARDING is open." "Close it without merging: gh pr close $ONBOARDING --repo $REPO --delete-branch"
  run gh pr close "$ONBOARDING" --repo "$REPO" --delete-branch \
    --comment "Closed by the repository setup wizard: the configuration is $RENOVATE_CONFIG." ||
    fail "gh pr close failed." "Read the error above."
else
  ok "no onboarding pull request is open"
fi
confirm "Does Renovate's installation reach $REPO_NAME through Only select repositories (not All repositories)?" ||
  fail "Renovate reaches every repository of $REPO_OWNER." "Choose Only select repositories: https://github.com/settings/installations"
pause "Press Enter to continue"

# ── 7. Repository settings ────────────────────────────────────────────────
stage "Apply the repository settings"

say "The ruleset on master ($RULESET_FILE), squash merge only, auto-merge,"
say "head branches deleted, Pages from GitHub Actions and the labels."
PROBLEMS=$(settings_problems)
if [[ -z "$PROBLEMS" ]]; then
  ok "they already read back as committed"
else
  while IFS= read -r line; do note "  not yet: $line"; done <<<"$PROBLEMS"
  say ""
  show pnpm -s repo:settings --dry-run ||
    fail "pnpm repo:settings --dry-run failed." "Read the error above."
  say ""
  confirm "Send these requests?" || fail "The settings are not applied." "Review them, then re-run."
  run pnpm -s repo:settings ||
    fail "pnpm repo:settings failed; it stops at the first failed request (above)." "Fix the cause, then re-run: what was applied reads back and is not planned again."
  say ""
  if $DRY_RUN; then
    note "A real run then checks that the ruleset is active on master with the"
    note "required checks of $RULESET_FILE, and reads back the merge settings,"
    note "the Pages source and the game-patch label."
  else
    PROBLEMS=$(settings_problems)
    [[ -z "$PROBLEMS" ]] || fail "The settings do not read back as committed:" "$PROBLEMS"
    ok "the ruleset is active on master with the required checks; the merge settings, the Pages source and the labels read back as committed"
  fi
fi
pause "Press Enter to continue"

finish
if $DRY_RUN; then
  note "Dry run: nothing was set, installed or applied."
else
  ok "$REPO has its GitHub App, Renovate and its settings."
fi
say ""
say "Next, now that the App exists:"
say "  - Rehearse the Patch watch (#200), a dry run first, then for real:"
say "    ${BOLD}gh workflow run patch-watch.yml --ref master -f simulate_current_patch=3.0.0.24267 -f dry_run=true${RESET}"
say "    ${BOLD}gh workflow run patch-watch.yml --ref master -f simulate_current_patch=3.0.0.24267${RESET}"
say "    then close its issue and pull request as their bodies say."
say "  - Human step 5 of $GUIDE (#46): the release workflow's dry run:"
say "    ${BOLD}gh workflow run release.yml --ref master -f dry-run=true${RESET}"
say ""
